/// <summary>
/// Find NVOrderTypeGroup by RecId
/// </summary>
/// <param name="_recId">RecId of the group</param>
/// <param name="_forUpdate">Select for update flag</param>
/// <returns>NVOrderTypeGroup record</returns>
public static NVOrderTypeGroup find(RecId _recId, boolean _forUpdate = false)
{
    NVOrderTypeGroup orderTypeGroup;

    if (!_recId)
    {
        return orderTypeGroup;
    }

    if (_forUpdate)
    {
        orderTypeGroup.selectForUpdate(_forUpdate);
    }

    select firstonly orderTypeGroup
        where orderTypeGroup.RecId == _recId;

    return orderTypeGroup;
}

/// <summary>
/// Find NVOrderTypeGroup by GroupId
/// </summary>
/// <param name="_groupId">Group ID (1-12)</param>
/// <param name="_forUpdate">Select for update flag</param>
/// <returns>NVOrderTypeGroup record</returns>
public static NVOrderTypeGroup findByGroupId(int _groupId, boolean _forUpdate = false)
{
    NVOrderTypeGroup orderTypeGroup;

    if (!_groupId)
    {
        return orderTypeGroup;
    }

    if (_forUpdate)
    {
        orderTypeGroup.selectForUpdate(_forUpdate);
    }

    select firstonly orderTypeGroup
        where orderTypeGroup.GroupId == _groupId;

    return orderTypeGroup;
}

/// <summary>
/// Check if group exists by RecId
/// </summary>
/// <param name="_recId">RecId of the group</param>
/// <returns>True if exists</returns>
public static boolean exist(RecId _recId)
{
    return _recId && (select firstonly RecId from NVOrderTypeGroup
                  where NVOrderTypeGroup.RecId == _recId).RecId != 0;
}
